-- 070: authored walkthrough definitions (Feature 004, T401). One row per guide: the VALIDATED Feature 002 definition as JSON plus its status.
-- Owner: dap_owner (applied by the migration runner as dap_owner). Same guards and tenant mechanism as 010 / 020.
-- Grants: SELECT, INSERT, UPDATE for dap_app only (no DELETE, no TRUNCATE): a guide is never removed, only unpublished.
-- RLS: enabled AND forced; the policy compares tenant_id to NULLIF(current_setting('app.tenant_id', true), '')::uuid so an unset tenant setting
-- yields zero rows instead of a cast error.
-- Ids are generated by the host (`wt-` + 12 lowercase hex) and are the only ids this table accepts: a maintainer never types one, so an authored id
-- can never equal a built-in id (profileUpdate, ...) or the reserved preview id (wt-preview). Every statement is idempotent (applied once by the runner,
-- and safe to run again).

DO $$
BEGIN
  IF current_user <> 'dap_owner' THEN RAISE EXCEPTION 'Walkthrough migration requires dap_owner'; END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.walkthrough_definitions (
  tenant_id uuid NOT NULL,
  walkthrough_id text NOT NULL CHECK (walkthrough_id ~ '^wt-[a-f0-9]{12}$'),
  status text NOT NULL CHECK (status IN ('draft','published')),
  definition jsonb NOT NULL CHECK (jsonb_typeof(definition) = 'object' AND octet_length(definition::text) <= 32768),
  created_by text NOT NULL CHECK (char_length(created_by) BETWEEN 1 AND 256),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_by text NOT NULL CHECK (char_length(updated_by) BETWEEN 1 AND 256),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, walkthrough_id)
);

DO $$
BEGIN
  IF (SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid = 'public.walkthrough_definitions'::regclass) <> 'dap_owner' THEN
    RAISE EXCEPTION 'Walkthrough definitions table must be owned by dap_owner';
  END IF;
END $$;

ALTER TABLE public.walkthrough_definitions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.walkthrough_definitions FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.walkthrough_definitions;
CREATE POLICY tenant_isolation ON public.walkthrough_definitions
  USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
  WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);

REVOKE ALL ON TABLE public.walkthrough_definitions FROM PUBLIC, dap_app;
GRANT SELECT, INSERT, UPDATE ON TABLE public.walkthrough_definitions TO dap_app;
